static boolean check(int x, int y, long num, long k) {
    long t1 = num / x;
    long t2 = num / y;
    long lcm = (long) x * (y / gcd(x, y));
    long t3 = num / lcm;
    return t1 + t2 - t3 * 2 >= k;
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}
